Definition pch_W (lo : Z) (sp : word) (P IN E : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (P, P + 80); (IN, IN + 8); (E, E + 24); (G_HTTP_CAT, G_HTTP_CAT + 64)]%Z.

Definition pch_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' p' E' c' g',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom usegs)
    /\ munch (pch_W lo sp P IN E) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' P (ParserCoreCells c' pad7 pad2)
    /\ rw_cells usegs m' IN [C8 (wz p')]
    /\ rw_cells usegs m' E (ErrCodeCells E')
    /\ rw_cells usegs m' (P + 288) [C8 (wz 0)]
    /\ bytes_at usegs m' p0 bs
    /\ pch_out c c' p0 (Z.of_nat (length bs)) p' E'
    /\ HttpCat m' g' /\ XStatics m'.

(* [comment removed for export] *)
Definition pch_pure (sp : word) (P IN E lo : Z) (c : pcore) (p0 : Z) (bs : list byte) : Prop :=
  pcore_ok c /\ pc_skip c < 2^62 /\ Z.of_nat (length bs) < 2^62
  /\ lo + 224 <= bv_unsigned sp (* [comment removed for export] *) /\ 0xb8000 <= lo /\ ((0 < p0 /\ p0 + Z.of_nat (length bs) <= 0x10000) \/ 0x95090 <= p0) /\ p0 + Z.of_nat (length bs) <= lo
  /\ bv_unsigned sp <= P /\ P + 296 <= 2^64 /\ bv_unsigned sp <= IN /\ IN + 8 <= 2^64 /\ bv_unsigned sp <= E /\ E + 24 <= 2^64
  /\ (P + 80 <= IN \/ IN + 8 <= P) /\ (P + 80 <= E \/ E + 24 <= P) /\ (IN + 8 <= E \/ E + 24 <= IN)
  /\ (P + 296 <= IN \/ IN + 8 <= P + 288) /\ (P + 296 <= E \/ E + 24 <= P + 288).

Definition pch_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P IN E lo : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (E0 : ecv) (g : bool),
  rw_cells usegs m P (ParserCoreCells c pad7 pad2) ->
  rw_cells usegs m IN [C8 (wz p0)] ->
  rw_cells usegs m E (ErrCodeCells E0) ->
  rw_cells usegs m (P + 288) [C8 (wz 0)] ->
  bytes_at usegs m p0 bs ->
  HttpCat m g -> XStatics m ->
  stk usegs m lo (bv_unsigned sp) ->
  pch_pure sp P IN E lo c p0 bs ->
  mem_inv usegs m ->
  evt usegs (pch_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz IN) (wz (Z.of_nat (length bs))) (wz E) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BP_PARSE_CHUNK_HEADER) fc None m (seg_rom usegs)).

(* [comment removed for export] *)
(* [comment removed for export] *)

Definition pch_ctx (m m1 : mem) (sp : word) (s6v s5v s4v s3v s2v s1v s0v rav : word) (P IN E lo : Z)
    (c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte) (pv : Z) (e1 e2 e3 : word) (g : bool)
    (tmp : list cell) : Prop :=
  rw_cells usegs m1 (bv_unsigned sp + -96) [C8 (wz pv)]
  /\ rw_cells usegs m1 (bv_unsigned sp + -88) tmp
  /\ rw_cells usegs m1 (bv_unsigned sp + -64) [C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells usegs m1 P (ParserCoreCells c1 pad7 pad2)
  /\ rw_cells usegs m1 IN [C8 (wz p0)]
  /\ rw_cells usegs m1 E [C8 e1; C8 e2; C8 e3]
  /\ rw_cells usegs m1 (P + 288) [C8 (wz 0)]
  /\ bytes_at usegs m1 p0 bs
  /\ HttpCat m1 g /\ XStatics m1
  /\ stk usegs m1 lo (bv_unsigned sp + -96)
  /\ munch (pch_W lo sp P IN E) m m1 /\ wmono usegs m m1 /\ mem_inv usegs m1.

(* [comment removed for export] *)
Definition pch_fcore (c c1 : pcore) (n : Z) : Prop :=
  pc_state c1 = pc_state c /\ pc_f c1 = pc_f c /\ pc_hlim c1 = pc_hlim c /\ pc_len c1 = pc_len c
  /\ pc_len0 c1 = pc_len0 c /\ pc_blim_has c1 = pc_blim_has c /\ 0 <= pc_blim c1 <= pc_blim c
  /\ 0 <= pc_skip c1 /\ (pc_skip c1 <= pc_skip c \/ pc_skip c1 < n)
  /\ 0 <= pc_skip c1 < 2^64 /\ 0 <= pc_f c1 < 2^14 /\ 0 <= pc_hlim c1 < 2^31.

Lemma pch_fail_exit : forall c c1 n e loc,
  pch_fcore c c1 n -> In e [HE_NEED_MORE; HE_BAD_CHUNK; HE_BAD_LINE_ENDING; HE_BAD_CHUNK_EXTENSION; HE_BODY_LIMIT] ->
  Z.even loc = true -> 4 <= loc -> loc + 1 < 2^64 ->
  pch_fail c c1 n (EC_http_loc e loc).
Proof.
  intros c c1 n e loc FC HE EV L1 L2.
  destruct FC as (F1 & F2 & F3 & F4 & F5 & F6 & F7 & F8 & F9 & _).
  assert (NZ : e <> 0) by (cbn in HE; unfold HE_NEED_MORE, HE_BAD_CHUNK, HE_BAD_LINE_ENDING, HE_BAD_CHUNK_EXTENSION, HE_BODY_LIMIT in HE; lia).
  assert (E32 : 0 <= e < 2^32) by (cbn in HE; unfold HE_NEED_MORE, HE_BAD_CHUNK, HE_BAD_LINE_ENDING, HE_BAD_CHUNK_EXTENSION, HE_BODY_LIMIT in HE; lia).
  unfold pch_fail, EC_http_loc, ec_make_loc, ec_failed, ec_ok. cbn [ec_val ec_cat ec_flags].
  replace (e =? 0) with false by (symmetry; apply Z.eqb_neq; exact NZ).
  unfold G_HTTP_CAT. repeat split; try fast_assumption; try lia.
  apply odd_loc1. exact EV.
Qed.

