Definition pch_exitA_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s4x s5x s6x
         s7 s6v s5v s4v s3v s2v s1v s0v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P IN E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (pv : Z) (e1 e2 e3 : word) (g : bool) (junk : list byte),
  pch_ctx m m1 sp s6v s5v s4v s3v s2v s1v s0v ra P IN E lo c1 pad7 pad2 p0 bs pv e1 e2 e3 g [CB 24 junk] ->
  pch_pure sp P IN E lo c p0 bs -> pch_fcore c c1 (Z.of_nat (length bs)) ->
  In e [HE_NEED_MORE; HE_BAD_CHUNK; HE_BAD_LINE_ENDING; HE_BAD_CHUNK_EXTENSION; HE_BODY_LIMIT] ->
  evt usegs (pch_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7 s8 s9 s10 s11 F fc P IN E lo c pad7 pad2 p0 bs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 (wz E) (wz P) a0 a1 a2 a3 a4 a5 a6 a7
              s2x (wz IN) s4x s5x s6x s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom usegs)).

Local Ltac pch_exitA_script e loc :=
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s4x s5x s6x s7 s6v s5v s4v s3v s2v s1v s0v s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P IN E lo c c1 pad7 pad2 p0 bs pv e1 e2 e3 g junk;
  intros CTX PURE FC HE;
  destruct CTX as (PCL & TMP & FRhi & PC & IT & EC & CBH & WIN & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & SK62 & N62 & LO & IMG & QLO & QHI & PLO & PHI & ILO & IHI & ELO & EHI & DPI & DPE & DIE & DCI & DCE);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  unfold pch_W, G_HTTP_CAT in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold VP_PARSER in PC;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold wz in *;
  (* [comment removed for export] *)
  steps_to 0x34360%Z;
  call_assignA_with (bv_unsigned sp + -96) (bv_unsigned sp + -88) e lo g junk;
  clear HC XS;
  lazymatch goal with
  | TMP' : rw_cells _ _ (bv_unsigned sp + -88) (ErrCodeCells _), HC : HttpCat _ true, XS : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP';
    (* [comment removed for export] *)
    steps_to 0x3e0c8%Z;
    expose_statics HC XS [(E, E + 24)]%Z;
    (* [comment removed for export] *)
    st1; st1; st1;
    (* [comment removed for export] *)
    step; step; step; step; step; step; step; step;
    join_frame TMP' FRhi (bv_unsigned sp + -88); join_frame PCL TMP' (bv_unsigned sp + -96);
    step; release_frame PCL ST' (bv_unsigned sp); step;
    lazymatch goal with
    | MU2 : munch [(E, E + 24)]%Z ?mx _, WM2 : wmono _ ?mx _ |- _ =>
        pch_finish p0 (EC_http_loc e loc) c1 true;
        [ (* [comment removed for export] *) right; split; [reflexivity|]; apply (pch_fail_exit _ _ _ _ _ FC HE); [reflexivity | lia | lia]
        | close_HttpCat_chunks
        | close_XStatics XS MU2 WM2 ]
    end
  end.
